348	    /**
349	     * Fixed city-to-region table used as the fall-back when deriving an owner's region.
350	     */
351	    private static final Map<String, String> CITY_REGION = Map.of(
352	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
