354	    /**
355	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
356	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
357	     */
358	    private static final Map<String, int[]> REGION_RANGE = Map.of(
359	        "NSW", new int[] {2000, 2099},
360	        "VIC", new int[] {3000, 3099},
361	        "QLD", new int[] {4000, 4099});
362	
363	    /**
364	     * Fixed region -> IANA timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
365	     * QLD->Australia/Brisbane), the single authority for {@link #getTimezone()}.
366	     */
367	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
368	        "NSW", "Australia/Sydney",
369	        "VIC", "Australia/Melbourne",
370	        "QLD", "Australia/Brisbane");
371	
372	    /**
373	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
374	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
375	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
376	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
377	     * the owner's {@link #getCustomerCode() customerCode}, so the create pipeline and
378	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
379	     * by the owner pipelines (e.g. postcode validation) rather than copied.
380	     */
381	    public static String regionFor(String postcode, String city) {
382	        String region = regionForPostcode(postcode);
383	        if (region != null) {
384	            return region;
385	        }
386	        String cityRegion = regionForCity(city);
387	        return cityRegion != null ? cityRegion : "UNKNOWN";
