396	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
397	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
398	     * range. */
399	    public static String regionForPostcode(String postcode) {
