431	     * QLD->Australia/Brisbane), or {@code null} when the region has no mapped timezone. Not
432	     * persisted — derived from {@link #getLocality()}.
433	     */
434	    @Transient
435	    public String getTimezone() {
436	        return REGION_TIMEZONE.get(getLocality());
437	    }
